-- Unified preset directory; configuration only, never auto-publish or enable execution.
CREATE TABLE pmt_preset_template (
    id BIGINT NOT NULL AUTO_INCREMENT COMMENT '内部主键',
    tenant_no VARCHAR(32) NOT NULL COMMENT '租户',
    template_code VARCHAR(32) NOT NULL COMMENT '稳定AP或EP编号',
    template_version INT NOT NULL COMMENT '目录版本',
    catalog_kind VARCHAR(24) NOT NULL COMMENT 'ACTIVITY/PAID_PRODUCT',
    category VARCHAR(32) NOT NULL COMMENT '活动机制或产品分类',
    name VARCHAR(100) NOT NULL COMMENT '模板名称',
    industry_tags JSON NOT NULL COMMENT '业态推荐标签，不是准入凭证',
    draft_schema JSON NOT NULL COMMENT '仅草稿建议，执行规则须经服务校验',
    required_capabilities JSON NOT NULL COMMENT '执行需要的真实能力',
    enabled TINYINT NOT NULL DEFAULT 0 COMMENT '默认禁用',
    version BIGINT NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
    deleted TINYINT NOT NULL DEFAULT 0 COMMENT '归档标志',
    created_at DATETIME(3) NOT NULL COMMENT '创建时间',
    updated_at DATETIME(3) NOT NULL COMMENT '更新时间',
    created_by VARCHAR(64) NOT NULL COMMENT '创建人',
    updated_by VARCHAR(64) NOT NULL COMMENT '更新人',
    PRIMARY KEY (id),
    UNIQUE KEY uk_preset (tenant_no,template_code,template_version),
    CHECK (template_version > 0),
    CHECK (catalog_kind IN ('ACTIVITY','PAID_PRODUCT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='活动与付费权益产品统一预置目录';

